def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray,
                     rest_capacity: float, demands: np.ndarray,
                     distance_matrix: np.ndarray) -> int:
    if unvisited_nodes.size == 0:
        return depot

    if current_node == depot:
        return int(unvisited_nodes[np.argmin(distance_matrix[depot][unvisited_nodes])])

    cur = distance_matrix[current_node][unvisited_nodes]
    to_depot_cand = distance_matrix[depot][unvisited_nodes]
    cur_depot = distance_matrix[current_node][depot]

    # Depot savings: how much is saved by linking current->j instead of current->depot->j
    savings = cur_depot + to_depot_cand - cur

    # Bias toward customers whose savings is high (i.e., far from depot in a useful way),
    # while still preferring nearby customers. Weight savings slightly under distance.
    score = cur - 0.5 * savings

    return int(unvisited_nodes[np.argmin(score)])
